-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLPool.json. Do not edit: change the chain file or ABI and regenerate.
-- CollectFees(address,uint128,uint128)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_pool__collect_fees',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as recipient,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64))))) as amount0,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64))))) as amount1
from {{ source('chain_base', 'logs') }}
where topic0 = '0x205860e66845f2bbc0966bfab80db9bf93fca93862ea2b9fcf6945748352b4a3'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
